#!/bin/bash
set -eo pipefail
/data1/home/sunyiq/miniconda3/envs/knet_clean/bin/python -X utf8 -B - <<'RECOVERY_DEPLOYMENT'

import base64, gzip, hashlib, io, json, shutil, subprocess, sys, tarfile
from pathlib import Path
OLD = Path("/data1/home/sunyiq/kalmannet_original_noise_multiday_20261007_attempt1")
NEW = Path("/data1/home/sunyiq/kalmannet_original_noise_multiday_20261008_recovery1")
PYTHON = "/data1/home/sunyiq/miniconda3/envs/knet_clean/bin/python"
def digest(path):
    value = hashlib.sha256()
    with path.open("rb") as handle:
        for part in iter(lambda: handle.read(1048576), b""):
            value.update(part)
    return value.hexdigest()
def load(path):
    return json.loads(path.read_text(encoding="utf-8"))
def verify(root, item):
    relative = Path(item["path"])
    path = root / relative
    if relative.is_absolute() or ".." in relative.parts or path.is_symlink() or not path.resolve().is_relative_to(root.resolve()):
        raise RuntimeError("File outside verified root: " + str(relative))
    if path.stat().st_size != item["bytes"] or digest(path) != item["sha256"]:
        raise RuntimeError("File fingerprint differs: " + str(relative))
    return path
if OLD.is_symlink() or OLD.resolve() != OLD.parent.resolve() / OLD.name:
    raise RuntimeError("Old experiment root is redirected")
if NEW.exists() or NEW.is_symlink():
    raise RuntimeError("New directory already exists; preserve and inspect, never redeploy")
old_job = load(OLD / "submissions/batch_000_195.json")["job_id"]
if old_job != "237583":
    raise RuntimeError("Old submission identity differs")
queue = subprocess.run(["squeue", "--user=sunyiq", "--name=original-noise-multiday", "--noheader", "--format=%i %t"], check=True, capture_output=True, text=True, timeout=45).stdout.strip()
accounting = subprocess.run(["sacct", "-X", "-n", "-P", "-j", old_job, "-o", "JobID,State,ExitCode"], check=True, capture_output=True, text=True, timeout=45).stdout.strip()
rows = [line.split("|") for line in accounting.splitlines() if line.split("|")[0] == old_job]
terminal = {"COMPLETED", "FAILED", "CANCELLED", "TIMEOUT", "OUT_OF_MEMORY", "NODE_FAIL", "PREEMPTED"}
if queue or len(rows) != 1 or rows[0][1].split()[0] not in terminal:
    raise RuntimeError("Old job not confirmed inactive; no directory created")
if digest(OLD / "package_manifest.json") != "102f9f857b2d87790fa2eff6e31d194bf3397f7a8b2f368666ea79e936f177ab" or digest(OLD / "remote_admission.json") != "05f9f137a720df383f00b66b9e5dc075b689da61aec489ac0926384a416da540":
    raise RuntimeError("Old deployment identity differs")
old_manifest = load(OLD / "package_manifest.json")
for item in old_manifest["files"]:
    verify(OLD, item)
data = base64.b64decode("", validate=True)
if len(data) != 140320 or hashlib.sha256(data).hexdigest() != "7bfb9de53d2558e84c9e7ca340be08dd3e1732eb5b086bf27836d1035513edc4":
    raise RuntimeError("Deployment overlay fingerprint differs")
with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as archive:
    members = archive.getmembers()
    files = {}
    for member in members:
        path = Path(member.name)
        if not member.isfile() or path.is_absolute() or ".." in path.parts or member.name in files or path.parts[:2] in (("results", "inputs"), ("results", "basins")):
            raise RuntimeError("Invalid overlay member")
        files[member.name] = archive.extractfile(member).read()
    manifest_bytes = files["package_manifest.json"]
    if hashlib.sha256(manifest_bytes).hexdigest() != "2e13b988a5f0250de8e6e0415b296e59be6e001f4d490199910845018d28ccd3":
        raise RuntimeError("New manifest differs")
    manifest = json.loads(manifest_bytes)
    admission_bytes = files["remote_admission.json"]
    if admission_bytes != files["results/review/source_admission.json"] or hashlib.sha256(admission_bytes).hexdigest() != "4f0d4cfddbc5f4130fe162dbff817a45870002db6fb363eac30122c17d5cf1e2":
        raise RuntimeError("Exact independent admission differs")
    admission = json.loads(admission_bytes)
    if admission["status"] != "PASS" or admission["manifest_sha256"] != "2e13b988a5f0250de8e6e0415b296e59be6e001f4d490199910845018d28ccd3" or admission["contract_sha256"] != "d22108134d2cfbab3719d7b8657af4105a64eb58f38bb4bc5329050980d2d12e":
        raise RuntimeError("Independent admission does not bind this package")
    contract = json.loads(files["results/control/contract_v5.json"])
    if hashlib.sha256(files["results/control/contract_v5.json"]).hexdigest() != "d22108134d2cfbab3719d7b8657af4105a64eb58f38bb4bc5329050980d2d12e":
        raise RuntimeError("Contract differs")
    carried = {item["basin_id"] for item in contract["carried_forward_results"]}
    if carried != {"01022500", "02297310"}:
        raise RuntimeError("Only two independently accepted complete results may be carried")
    copy_items = [item for item in manifest["files"] if Path(item["path"]).parts[:2] in (("results", "inputs"), ("results", "basins"))]
    if len([item for item in copy_items if item["path"].startswith("results/inputs/")]) != 926:
        raise RuntimeError("Frozen input coverage differs")
    carried_files = {item["path"] for item in copy_items if item["path"].startswith("results/basins/")}
    if carried_files != {"results/basins/" + basin + suffix for basin in carried for suffix in (".json", ".npz")}:
        raise RuntimeError("Partial or unaccepted basin would be copied")
    for item in copy_items:
        verify(OLD, item)
    NEW.mkdir()
    for name in ("code", "results/control", "results/basins", "results/review", "logs", "tmp", "submissions"):
        (NEW / name).mkdir(parents=True, exist_ok=True)
    for item in copy_items:
        target = NEW / item["path"]
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(OLD / item["path"], target)
    for name, contents in files.items():
        target = NEW / name
        target.parent.mkdir(parents=True, exist_ok=True)
        with target.open("xb") as handle:
            handle.write(contents)
for item in manifest["files"]:
    verify(NEW, item)
completed = subprocess.run([PYTHON, "-X", "utf8", "-B", str(NEW / "code/remote.py"), "check"], check=True, capture_output=True, text=True, timeout=180)
record = {"status": "ISOLATED_RECOVERY_DEPLOYED_VERIFIED_NO_SUBMISSION", "old_job": old_job, "old_accounting": accounting, "old_queue": queue, "remote_root": str(NEW), "manifest_sha256": "2e13b988a5f0250de8e6e0415b296e59be6e001f4d490199910845018d28ccd3", "contract_sha256": "d22108134d2cfbab3719d7b8657af4105a64eb58f38bb4bc5329050980d2d12e", "admission_sha256": "4f0d4cfddbc5f4130fe162dbff817a45870002db6fb363eac30122c17d5cf1e2", "copied_input_files": 926, "carried_complete_basins": sorted(carried), "scientific_jobs_submitted": 0, "old_directory_modified": False, "remote_check_stdout": completed.stdout.strip()}
with (NEW / "results/control/deployment_identity.json").open("x", encoding="utf-8") as handle:
    json.dump(record, handle, indent=2)
    handle.write("\n")
print("DEPLOYMENT_JSON=" + json.dumps(record), flush=True)

RECOVERY_DEPLOYMENT
